create table if not exists public.push_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,couple_id uuid not null references public.couples(id) on delete cascade,endpoint text not null unique,p256dh text not null,auth text not null,user_agent text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.push_subscriptions enable row level security;
drop policy if exists "push own select" on public.push_subscriptions;drop policy if exists "push own insert" on public.push_subscriptions;drop policy if exists "push own update" on public.push_subscriptions;drop policy if exists "push own delete" on public.push_subscriptions;
create policy "push own select" on public.push_subscriptions for select to authenticated using(user_id=auth.uid());create policy "push own insert" on public.push_subscriptions for insert to authenticated with check(user_id=auth.uid());create policy "push own update" on public.push_subscriptions for update to authenticated using(user_id=auth.uid()) with check(user_id=auth.uid());create policy "push own delete" on public.push_subscriptions for delete to authenticated using(user_id=auth.uid());
alter table public.reminders add column if not exists last_notified_at timestamptz;
do $$ begin if not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='messages') then alter publication supabase_realtime add table public.messages; end if; exception when undefined_object then null; end $$;